package dev.hoi.client.map;

import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.ScreenMapCursor;
import dev.hoi.protocol.*;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.client.input.MouseButtonInfo;
import java.util.*;

final class MapCommanderGroupsRenderTest {
    private static Card card(String id,Mode role,String parent,List<String> divisions){var rows=role==Mode.ARMY_GROUP?List.<Member>of():divisions.stream().map(d->new Member(d,d,"대기 중","unit_hud/infantry","",1,new Open(Mode.ARMY_UNITS,id))).toList();return new Card(id,id,"","politics/empty/leader","","",divisions.size(),24,"",role,new Panel(parent,"",null,rows,divisions.size(),List.of(),divisions,role==Mode.ARMY_GROUP?(id.equals("G1")?0x730bdb:0x0bdbdb):null,role==Mode.ARMY_GROUP?List.of(0x730bdb,0x0bdbdb):List.of()));}
    static void run(ClientGameTestContext game,ProtocolMenuView menu){
        try{for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
            var source=new View[1];var requests=new ArrayList<Open>();var commands=new ArrayList<ProtocolCommanderOrders.Command>();game.getInput().resizeWindow(size[0],size[1]);
            game.runOnClient(client->{client.options.guiScale().set(2);ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderHud.reset();MapUnitHud.reset();MapCommanderHud.requestObserver=requests::add;MapCommanderOrders.commandObserver=commands::add;MapCommanderOrders.selectionObserver=selection->{};source[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.ARMY,List.of(card("G1",Mode.ARMY_GROUP,"",List.of("a1","a2","b1")),card("G2",Mode.ARMY_GROUP,"",List.of("c1")),card("A",Mode.ASSIGN_ARMY,"G1",List.of("a1","a2")),card("B",Mode.ASSIGN_ARMY,"G1",List.of("b1")),card("C",Mode.ASSIGN_ARMY,"G2",List.of("c1"))));MapCommanderHud.accept(source[0]);MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(UUID.randomUUID().toString(),0,"KOR",source[0].dimension(),""));MapCommanderPanels.select("G1",false);MapCommanderPanels.select("G2",true);});
            game.setScreen(ScreenMapCursor::new);game.waitTicks(3);
            game.runOnClient(client->{var a=portrait("A");var b=portrait("B");var group=portrait("G1");if(!(a.x()<b.x()&&b.x()<group.x()))throw new AssertionError("Member armies must be immediately left of parent");if(MapCommanderHud.bands().size()!=2)throw new AssertionError("Independent groups need independent background bands");if(MapCommanderHud.bands().get(0).color()==MapCommanderHud.bands().get(1).color())throw new AssertionError("Fixture groups must have distinct colors");checkSelection();var close=control(group,true);click(close,InputConstants.MOUSE_BUTTON_RIGHT);if(!requests.isEmpty()||!commands.isEmpty())throw new AssertionError("Control right click must not reassign or issue map input");click(control(group,false),InputConstants.MOUSE_BUTTON_LEFT);checkSelection();});game.waitTicks(2);
            game.runOnClient(client->{if(portraitPresent("A")||portraitPresent("B")||!portraitPresent("G1")||!portraitPresent("C")||MapCommanderHud.bands().size()!=1)throw new AssertionError("Collapse must hide only selected group's army block");MapCommanderHud.accept(source[0]);checkSelection();});game.waitTicks(2);game.takeScreenshot("hoi-card-group-collapsed-selection-retained-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{if(portraitPresent("A"))throw new AssertionError("Refresh reopened a collapsed group");click(control(portrait("G1"),false),InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);game.takeScreenshot("hoi-card-groups-expanded-left-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{checkSelection();MapCommanderPanels.select("A",false);});game.waitTicks(2);
            game.runOnClient(client->{click(control(portrait("A"),false),InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);
            game.runOnClient(client->{if(!MapUnitHud.selectedKeys().equals(Set.of("unit/a1","unit/a2"))||MapCommanderPanels.hits().stream().anyMatch(h->h.tip().startsWith("a1\n")))throw new AssertionError("Army list collapse must preserve selected division IDs while hiding rows");click(control(portrait("A"),true),InputConstants.MOUSE_BUTTON_LEFT);if(!MapUnitHud.selectedKeys().isEmpty()||!requests.isEmpty()||!commands.isEmpty())throw new AssertionError("Card X must deselect without a dissolve or command request");if(source[0].cards().size()!=5)throw new AssertionError("Presentation controls changed formation data");});
            game.waitTicks(2);game.runOnClient(client->{var swatch=MapCommanderHud.boxes().stream().filter(b->b.tip().startsWith("집단군 색상 ·")&&b.x()>=portrait("G1").x()&&b.x()<portrait("G1").x()+portrait("G1").width()).findFirst().orElseThrow();click(swatch,InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);
            game.runOnClient(client->{var choice=MapCommanderHud.boxes().stream().filter(b->b.tip().equals("집단군 색상 #0BDBDB")).findFirst().orElseThrow();click(choice,InputConstants.MOUSE_BUTTON_LEFT);if(commands.size()!=1||!commands.getFirst().action().equals("GROUP_COLOR")||!commands.getFirst().selection().equals(List.of("G1","rgb/"+0x0bdbdb)))throw new AssertionError("Color swatch must send one exact authenticated group-color request");if(MapCommanderHud.groups.color("G1",source[0])!=0xff730bdb)throw new AssertionError("Color must wait for authoritative snapshot");var updated=source[0].cards().stream().map(c->{if(!c.id().equals("G1"))return c;var panel=c.panel();return new Card(c.id(),c.name(),c.leader(),c.portrait(),c.marshal(),c.marshalPortrait(),c.count(),c.capacity(),c.detail(),c.role(),new Panel(panel.parent(),panel.commander(),panel.leader(),panel.members(),panel.total(),panel.controls(),panel.divisionIds(),0x0bdbdb,panel.palette()));}).toList();source[0]=new View(source[0].country(),source[0].dimension(),source[0].branch(),updated);var issued=MapCommanderOrders.currentContext();MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(issued.token(),1,issued.country(),issued.dimension(),""));MapCommanderHud.accept(source[0]);});game.waitTicks(2);
            game.runOnClient(client->{if(MapCommanderHud.bands().stream().filter(b->b.owner().equals("G1")).anyMatch(b->b.color()!=0xff0bdbdb))throw new AssertionError("Group backing must use received RGB exactly");});game.takeScreenshot("hoi-card-group-authoritative-color-"+size[0]+"x"+size[1]+"-gui2");
            game.runOnClient(client->{MapCommanderHud.reset();commands.clear();requests.clear();var members=List.of(new Member("f1","기동부대 1","대기 중","unit_hud/navy_destroyer","",1,new Open(Mode.NAVAL_MISSION,"f1")),new Member("f2","기동부대 2","대기 중","unit_hud/navy_destroyer","",1,new Open(Mode.NAVAL_MISSION,"f2")));var fleet=new Card("F","함대","","politics/empty/leader","","",2,10,"",Mode.NAVY_FLEET,new Panel("","",null,members,2,List.of()));MapCommanderHud.accept(new View("KOR",source[0].dimension(),Mode.NAVY_HQ,List.of(fleet)));MapCommanderPanels.select("F",false);});game.waitTicks(2);
            game.runOnClient(client->{if(!fleetRowVisible()||!fleetSelection())throw new AssertionError("Expanded fleet must show actual member rows and select both task forces");click(control(portrait("F"),false),InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);
            game.runOnClient(client->{if(!fleetSelection())throw new AssertionError("Fleet fold changed exact selected task forces");if(MapCommanderHud.groups.rowsVisible("F")||fleetRowVisible())throw new AssertionError("Fleet fold did not hide detail rows");if(MapCommanderPanels.hits().stream().noneMatch(h->h.tip().startsWith("기동부대 1\n")))throw new AssertionError("Fold must preserve bottom mission target controls");click(control(portrait("F"),true),InputConstants.MOUSE_BUTTON_RIGHT);if(!MapCommanderPanels.selected("F")||!commands.isEmpty()||!requests.isEmpty())throw new AssertionError("Fleet control right-click must not mutate selection or membership");});game.takeScreenshot("hoi-fleet-card-folded-selection-retained-"+size[0]+"x"+size[1]+"-gui2");game.runOnClient(client->{click(control(portrait("F"),false),InputConstants.MOUSE_BUTTON_LEFT);});game.waitTicks(2);game.runOnClient(client->{if(!fleetRowVisible()||!fleetSelection())throw new AssertionError("Fleet expansion must restore rows without changing selection");click(control(portrait("F"),true),InputConstants.MOUSE_BUTTON_LEFT);if(!MapCommanderPanels.commandSelection().isEmpty()||!commands.isEmpty()||!requests.isEmpty())throw new AssertionError("Fleet X deselects without disbanding task forces");});
        }}finally{game.runOnClient(client->{MapCommanderHud.requestObserver=null;MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});}
    }
    private static boolean fleetSelection(){return new HashSet<>(MapCommanderPanels.commandSelection()).equals(Set.of("navy/f1","navy/f2"));}
    private static boolean fleetRowVisible(){var client=net.minecraft.client.Minecraft.getInstance();var units=new dev.hoi.client.ui.UiUnits(client.getWindow().getGuiScaledWidth(),client.getWindow().getGuiScaledHeight());return MapCommanderPanels.hits().stream().anyMatch(h->h.x()<units.size(250)&&h.tip().startsWith("기동부대 1\n"));}
    private static void checkSelection(){if(!MapUnitHud.selectedKeys().equals(Set.of("unit/a1","unit/a2","unit/b1","unit/c1")))throw new AssertionError("Folding changed selected divisions");}
    private static boolean portraitPresent(String id){return MapCommanderHud.boxes().stream().anyMatch(b->b.request()!=null&&b.request().target().equals(id)&&(b.request().mode()==Mode.ASSIGN_ARMY||b.request().mode()==Mode.ASSIGN_GROUP_MARSHAL||b.request().mode()==Mode.NAVY_FLEET));}
    private static MapCommanderHud.Box portrait(String id){return MapCommanderHud.boxes().stream().filter(b->b.request()!=null&&b.request().target().equals(id)&&(b.request().mode()==Mode.ASSIGN_ARMY||b.request().mode()==Mode.ASSIGN_GROUP_MARSHAL||b.request().mode()==Mode.NAVY_FLEET)).findFirst().orElseThrow();}
    private static MapCommanderHud.Box control(MapCommanderHud.Box portrait,boolean close){return MapCommanderHud.boxes().stream().filter(b->b.action()!=null&&b.x()>=portrait.x()+portrait.width()/2&&b.x()<portrait.x()+portrait.width()&&(close?b.y()<portrait.y():b.y()>portrait.y()&&b.y()<portrait.y()+portrait.height())).findFirst().orElseThrow();}
    private static void click(MapCommanderHud.Box box,int button){var screen=net.minecraft.client.Minecraft.getInstance().gui.screen();var event=new MouseButtonEvent(box.x()+box.width()/2.,box.y()+box.height()/2.,new MouseButtonInfo(button,0));if(!screen.mouseClicked(event,false))throw new AssertionError("Card control did not consume actual screen input");screen.mouseReleased(event);}
}
